/**
 * Dashboard Component - VERSION CORRIGÉE ROBUSTE
 */

import React, { useState, useEffect, useMemo } from "react";
import { attendanceAPI } from "./api_service";

const COLORS = {
  primary: "#4F46E5",
  success: "#10B981",
  danger: "#EF4444",
  warning: "#F59E0B",
  textMain: "#1E293B",
  textMuted: "#64748B",
  border: "#E2E8F0"
};

const Dashboard = () => {
  const [stats, setStats] = useState({
    active_students: 0,
    present_today: 0,
    absent_today: 0,
    summary: {
      unique_students: 0,
      total_records: 0,
      avg_confidence: 0,
      max_confidence: 0,
      min_confidence: 0
    }
  });

  const [attendanceLog, setAttendanceLog] = useState([]);
  const [statusList, setStatusList] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  /**
   * ================= LOAD DATA =================
   */
  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);

      const [statsRes, logRes, statusRes] = await Promise.all([
        attendanceAPI.getStats(),
        attendanceAPI.getTodayLog(),
        attendanceAPI.getStatus()
      ]);

      // 🔴 SAFE STATS (évite crash backend)
      const safeStats = {
        active_students: statsRes?.data?.active_students || 0,
        present_today: statsRes?.data?.present_today || 0,
        absent_today: statsRes?.data?.absent_today || 0,
        summary: {
          unique_students: statsRes?.data?.summary?.unique_students || 0,
          total_records: statsRes?.data?.summary?.total_records || 0,
          avg_confidence: statsRes?.data?.summary?.avg_confidence || 0,
          max_confidence: statsRes?.data?.summary?.max_confidence || 0,
          min_confidence: statsRes?.data?.summary?.min_confidence || 0
        }
      };

      setStats(safeStats);
      setAttendanceLog(logRes?.data?.records || []);
      setStatusList(statusRes?.data?.students || []);

      setError(null);
    } catch (err) {
      console.error("Dashboard error:", err);
      setError("Erreur lors du chargement des données");
    } finally {
      setLoading(false);
    }
  };

  /**
   * ================= STATS CARDS =================
   */
  const statCards = useMemo(() => {
    const total = stats.active_students || 0;
    const present = stats.present_today || 0;

    const attendanceRate =
      total > 0 ? Math.round((present / total) * 100) : 0;

    return [
      {
        label: "Total Étudiants",
        value: total,
        icon: "👥",
        color: COLORS.primary
      },
      {
        label: "Présents aujourd'hui",
        value: present,
        icon: "✅",
        color: COLORS.success
      },
      {
        label: "Absents aujourd'hui",
        value: stats.absent_today,
        icon: "❌",
        color: COLORS.danger
      },
      {
        label: "Taux de présence",
        value: `${attendanceRate}%`,
        icon: "📈",
        color: "#8B5CF6"
      }
    ];
  }, [stats]);

  /**
   * ================= LOADING =================
   */
  if (loading) {
    return (
      <div style={styles.loading}>
        ⏳ Chargement du dashboard...
      </div>
    );
  }

  return (
    <div style={styles.container}>

      {error && (
        <div style={styles.error}>
          ⚠️ {error}
        </div>
      )}

      {/* ================= STATS ================= */}
      <div style={styles.statsGrid}>
        {statCards.map((stat, i) => (
          <div key={i} style={styles.statCard}>
            <div
              style={{
                ...styles.statIcon,
                backgroundColor: stat.color + "20",
                color: stat.color
              }}
            >
              {stat.icon}
            </div>

            <div>
              <p style={styles.statLabel}>{stat.label}</p>
              <h3 style={styles.statValue}>{stat.value}</h3>
            </div>
          </div>
        ))}
      </div>

      {/* ================= GRID ================= */}
      <div style={styles.grid}>

        {/* Attendance Log */}
        <div style={styles.card}>
          <h3 style={styles.cardTitle}>Journal de présence</h3>

          <table style={styles.table}>
            <thead>
              <tr>
                <th>Étudiant</th>
                <th>Heure</th>
                <th>Confiance</th>
              </tr>
            </thead>

            <tbody>
              {attendanceLog.slice(0, 10).map((record, i) => (
                <tr key={i}>
                  <td>{record.student || "N/A"}</td>
                  <td>{record.timestamp || "-"}</td>
                  <td>
                    <span style={styles.badge}>
                      {record.confidence
                        ? `${(record.confidence * 100).toFixed(1)}%`
                        : "0%"}
                    </span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Summary */}
        <div style={styles.card}>
          <h3 style={styles.cardTitle}>Résumé</h3>

          <div style={styles.summary}>
            <div>
              <span>Étudiants uniques</span>
              <b>{stats.summary.unique_students}</b>
            </div>

            <div>
              <span>Total scans</span>
              <b>{stats.summary.total_records}</b>
            </div>

            <div>
              <span>Confiance moyenne</span>
              <b>
                {(stats.summary.avg_confidence * 100).toFixed(1)}%
              </b>
            </div>

            <div>
              <span>Confiance max</span>
              <b>
                {(stats.summary.max_confidence * 100).toFixed(1)}%
              </b>
            </div>
          </div>
        </div>
      </div>

      {/* ================= STATUS TABLE ================= */}
      <div style={styles.cardFull}>
        <h3 style={styles.cardTitle}>Statut des étudiants</h3>

        <table style={styles.table}>
          <thead>
            <tr>
              <th>Nom</th>
              <th>Email</th>
              <th>Statut</th>
            </tr>
          </thead>

          <tbody>
            {statusList.map((s, i) => (
              <tr key={i}>
                <td>{s.name}</td>
                <td>{s.email || "N/A"}</td>
                <td>
                  <span
                    style={{
                      ...styles.badge,
                      backgroundColor: s.present ? "#DCFCE7" : "#FEE2E2",
                      color: s.present ? "#166534" : "#991B1B"
                    }}
                  >
                    {s.present ? "Présent" : "Absent"}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* REFRESH */}
      <button onClick={loadData} style={styles.refresh}>
        🔄 Rafraîchir
      </button>
    </div>
  );
};

